  reg [3:0] state;
  parameter A = 4'b0001, B = 4'b0010, C = 4'b0100, D = 4'b1000;
  always @(posedge CLK) begin
    case (state)
      A: if (X == 1'b1 && Y == 1'b0) state <= B;
         else if (X == 1'b0 && Y == 1'b1) state <= D;
         else if (X == 1'b1 && Y == 1'b1) state <= C;
         else state <= A;
      B: if (X == 1'b1 && Y == 1'b1) state <= C;
         else if (X == 1'b0 && Y == 1'b0) state <= A;
         else state <= B;
      C: if (X == 1'b1 && Y == 1'b1) state <= D;
         else state <= C;
      D: if (X == 1'b1 && Y == 1'b1) state <= C;
         else state <= D;
      default: state <= A;
    endcase
  end
  always @(state) begin
    case(state)
      A, B, D: Z = 1'b0;
      C: Z = 1'b1;
